void Integrations::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Delete("/integrations/commerce/{external_business_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleIntegrationscommerceexternalBusinessIdDeleteRequest(req, res, auth);
    });
    svr.Get("/integrations/commerce/{external_business_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleIntegrationscommerceexternalBusinessIdGetRequest(req, res, auth);
    });
    svr.Patch("/integrations/commerce/{external_business_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleIntegrationscommerceexternalBusinessIdPatchRequest(req, res, auth);
    });
    svr.Post("/integrations/commerce", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleIntegrationscommercePostRequest(req, res, auth);
    });
    svr.Post("/integrations/logs", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleIntegrationslogsPostRequest(req, res, auth);
    });
    svr.Get("/integrations/{id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleIntegrationsidGetRequest(req, res, auth);
    });
    svr.Get("/integrations", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleIntegrationsGetRequest(req, res, auth);
    });
}

